<script setup>
import { computed } from 'vue'
import { useRoute } from 'vue-router'
import { PhArrowRight, PhArrowUpRight, PhBellRinging, PhClock, PhDownloadSimple, PhEnvelopeSimple, PhFilePdf, PhGavel, PhMapPin, PhPhone, PhUserCircle, PhUsersThree } from '@phosphor-icons/vue'
import PageIntro from '../components/PageIntro.vue'
import { cmsContent, formatCmsDate } from '../stores/cmsContent'
import NotFoundView from './NotFoundView.vue'
import { departmentFaqs, departmentSectors } from '../lib/departmentContent.js'
import { departmentPublications } from '../lib/departmentPublications.js'

const route = useRoute()
const department = computed(() => cmsContent.departments.find((item) => item.slug === route.params.slug))
const sectors = computed(() => departmentSectors(department.value))
const faqs = computed(() => departmentFaqs(department.value))
const notices = computed(() => departmentPublications(department.value, cmsContent.publications))
const publicBodies = computed(() => Array.isArray(department.value?.publicBodies) ? department.value.publicBodies.filter((body) => body?.name) : [])
const hod = computed(() => ({
  name: department.value?.hodName || '',
  title: department.value?.hodTitle || department.value?.lead || 'Head of Department',
  photo: department.value?.hodPhoto || '',
  message: department.value?.hodMessage || '',
}))
const featuredLeaders = computed(() => department.value?.featureTeamAsLeadership && Array.isArray(department.value?.team) ? department.value.team.filter((member) => member?.name && member?.role) : [])
const hasHodProfile = computed(() => Boolean(department.value?.hodName || department.value?.hodPhoto || department.value?.hodMessage || featuredLeaders.value.length))
const phoneHref = computed(() => department.value?.phone ? `tel:${department.value.phone.replace(/[^+\d]/g, '')}` : '')
</script>

<template>
  <div v-if="department" class="department-page">
    <PageIntro :page-key="`directorate-${department.slug}`" fallback-key="directorate-default" eyebrow="Municipal department" :title="department.name" :description="department.summary">
      <template #breadcrumb><RouterLink to="/departments">Departments</RouterLink><span class="mx-2 text-ink/25">/</span><span>{{ department.shortName }}</span></template>
    </PageIntro>

    <section v-if="hasHodProfile" class="department-hod" aria-labelledby="department-hod-title">
      <div v-if="featuredLeaders.length" class="site-container department-leadership">
        <header><p>Department leadership</p><h2 id="department-hod-title">Technical officers leading this department</h2></header>
        <div class="department-leadership__grid">
          <article v-for="leader in featuredLeaders" :key="`${leader.name}-${leader.role}`">
            <div class="department-leader__portrait"><img v-if="leader.photo" :src="leader.photo" :alt="`${leader.name}, ${leader.role}`" /><PhUserCircle v-else :size="56" weight="duotone" /></div>
            <div><p>{{ leader.role }}</p><h3>{{ leader.name }}</h3><small>{{ department.name }}</small></div>
          </article>
        </div>
      </div>
      <div v-else class="site-container department-hod__inner" :class="{ 'department-hod__inner--with-message': hod.message }">
        <div class="department-hod__portrait"><img v-if="hod.photo" :src="hod.photo" :alt="hod.name ? `${hod.name}, ${hod.title}` : hod.title" /><PhUserCircle v-else :size="64" weight="duotone" /></div>
        <div class="department-hod__identity"><p>Head of Department</p><h2 id="department-hod-title">{{ hod.name || hod.title }}</h2><span v-if="hod.name">{{ hod.title }}</span><small>{{ department.name }}</small></div>
        <blockquote v-if="hod.message">“{{ hod.message }}”</blockquote>
      </div>
    </section>

    <nav class="department-jump" aria-label="On this page"><div class="site-container"><strong>On this page</strong><a href="#overview">Overview</a><a href="#services">Services</a><a href="#department-notices">Notice board</a><a href="#sectors">Structure</a><a href="#department-faqs">FAQs</a><a href="#department-contact">Contact</a></div></nav>

    <div class="site-container department-layout">
      <main class="department-content">
        <section id="overview" class="department-section department-mandate" tabindex="-1">
          <p class="section-kicker">01 · Department overview</p><h2>Mandate and public responsibility</h2><p>{{ department.mandate }}</p>
          <dl class="department-facts"><div><dt>Services listed</dt><dd>{{ department.services?.length || 0 }}</dd></div><div><dt>Sectors and units</dt><dd>{{ sectors.length }}</dd></div><div><dt>Published documents</dt><dd>{{ notices.length }}</dd></div></dl>
        </section>

        <section id="services" class="department-section department-services" tabindex="-1">
          <p class="section-kicker">02 · Public services</p><div class="department-section__heading"><h2>How this department can help</h2><span>{{ department.services?.length || 0 }} service routes</span></div>
          <ul v-if="department.services?.length"><li v-for="service in department.services" :key="service"><PhArrowRight :size="16" weight="bold" />{{ service }}</li></ul>
          <div v-else class="department-empty"><h3>Service information is being prepared</h3><p>Contact the responsible office for current guidance.</p></div>
        </section>

        <section id="department-notices" class="department-section department-notices" tabindex="-1">
          <p class="section-kicker">03 · Departmental Notice Board</p><div class="department-section__heading"><h2>Official documents and notices</h2><RouterLink to="/municipal-notice-board">View the full Notice Board <PhArrowUpRight :size="17" /></RouterLink></div>
          <div v-if="notices.length" class="department-notice-list"><article v-for="notice in notices.slice(0, 6)" :key="`${notice.title}-${notice.referenceNumber || ''}`"><span><PhFilePdf :size="24" weight="duotone" /></span><div><p>{{ notice.category || 'Municipal document' }}<time v-if="notice.publishedDate" :datetime="notice.publishedDate">{{ formatCmsDate(notice.publishedDate) }}</time></p><h3>{{ notice.title }}</h3><small v-if="notice.referenceNumber">Ref: {{ notice.referenceNumber }}</small></div><a v-if="notice.url" :href="notice.url" :download="notice.fileName || undefined" target="_blank" rel="noreferrer" :aria-label="`Download ${notice.title}`"><PhDownloadSimple :size="18" weight="bold" /><span>Download</span></a><em v-else>File pending</em></article></div>
          <div v-else class="department-empty department-empty--notice"><PhBellRinging :size="26" /><div><h3>No departmental notices are currently published</h3><p>Approved documents will appear here when staff assign them to this department in the CMS.</p></div></div>
        </section>

        <section id="sectors" class="department-section" tabindex="-1">
          <p class="section-kicker">04 · Department structure</p><div class="department-section__heading"><h2>Sectors and units</h2><span>{{ sectors.length }} {{ sectors.length === 1 ? 'entry' : 'entries' }}</span></div>
          <div v-if="sectors.length" class="department-sectors"><article v-for="(sector, index) in sectors" :key="sector.id"><span>{{ String(index + 1).padStart(2, '0') }}</span><div><h3>{{ sector.name }}</h3><p v-if="sector.summary">{{ sector.summary }}</p></div></article></div>
          <div v-else class="department-empty"><h3>Structure information is being prepared</h3><p>Contact the department for its current organisational structure.</p></div>
        </section>

        <section id="department-faqs" class="department-section" tabindex="-1">
          <p class="section-kicker">05 · Public guidance</p><div class="department-section__heading"><h2>Frequently asked questions</h2><span>{{ faqs.length }} {{ faqs.length === 1 ? 'answer' : 'answers' }}</span></div>
          <div v-if="faqs.length" class="department-faqs"><article v-for="(faq, index) in faqs" :key="faq.id"><span>{{ String(index + 1).padStart(2, '0') }}</span><div><h3>{{ faq.question }}</h3><p>{{ faq.answer }}</p></div></article></div>
          <div v-else class="department-empty"><h3>No departmental FAQs have been published yet</h3><p>Use the official contact route for current guidance.</p></div>
        </section>

        <section v-if="publicBodies.length" id="public-bodies" class="department-section" tabindex="-1"><p class="section-kicker">Community representation</p><article v-for="body in publicBodies" :key="body.id || body.name" class="public-body-document"><div class="public-body-document__icon"><PhFilePdf :size="30" weight="duotone" /><span>PDF</span></div><div><p>{{ body.acronym || 'Public forum' }}</p><h2>{{ body.name }}</h2><div>{{ body.summary }}</div><small v-if="body.lastReviewed">Official directory reviewed {{ formatCmsDate(body.lastReviewed) }}</small></div><a v-if="body.documentUrl" :href="body.documentUrl" :download="body.documentFileName || undefined" target="_blank" rel="noreferrer"><PhDownloadSimple :size="18" weight="bold" /> Download member directory</a><RouterLink v-else to="/municipal-notice-board">Find documents on the Notice Board <PhArrowRight :size="16" /></RouterLink></article></section>

        <details v-if="department.authority" class="department-authority"><summary><span><PhGavel :size="22" /> Legal authority</span></summary><p>{{ department.authority }}</p></details>
        <section v-if="department.team?.length && !department.featureTeamAsLeadership" class="department-section"><p class="section-kicker">Department team</p><h2>People serving this department</h2><div class="department-team"><article v-for="member in department.team" :key="`${member.name}-${member.role}`"><img v-if="member.photo" :src="member.photo" :alt="`${member.name}, ${member.role}`" loading="lazy" /><span v-else><PhUserCircle :size="32" /></span><div><p>{{ member.role }}</p><h3>{{ member.name }}</h3></div></article></div></section>
      </main>

      <aside id="department-contact" class="department-contact">
        <p>Contact this department</p><PhUsersThree :size="30" /><h2>{{ department.lead || `Contact ${department.name}` }}</h2>
        <a v-if="department.contact" :href="`mailto:${department.contact}`"><PhEnvelopeSimple :size="18" />{{ department.contact }}</a><a v-if="phoneHref" :href="phoneHref"><PhPhone :size="18" />{{ department.phone }}</a>
        <div v-if="department.officeLocation"><PhMapPin :size="18" /><span><small>Office</small>{{ department.officeLocation }}</span></div><div v-if="department.officeHours"><PhClock :size="18" /><span><small>Public hours</small>{{ department.officeHours }}</span></div>
        <RouterLink to="/contact#contact-details">Council contact details <PhArrowRight :size="16" weight="bold" /></RouterLink>
      </aside>
    </div>
  </div>
  <div v-else-if="!cmsContent.loaded" class="site-container py-20" role="status">Loading department…</div><NotFoundView v-else />
</template>

